"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0db/roll"
import { Avatar, type AvatarProps } from "@/components/ui/avatar"
import { Spinner } from "@/components/ui/spinner"

type MessageProps = React.ComponentProps<"article"> & {
  /** Theirs sit at the start in roman; yours sit at the end, in italic. */
  from?: "them" | "you"
  /** Writes the body in from the left when it mounts. */
  arriving?: boolean
  /**
   * script: a play text. The name stands in the margin, the words in the column, and only the type says who is speaking.
   * quote: no face. A large quotation mark opens theirs at the start and closes yours at the end.
   */
  variant?: "default" | "script" | "quote"
}

/** A message: what they wrote is roman, what you wrote is italic. */
function Message({ className, from = "them", arriving, variant = "default", ...props }: MessageProps) {
  return (
    <article
      data-slot="message"
      data-from={from}
      data-arriving={arriving || undefined}
      data-variant={variant === "default" ? undefined : variant}
      className={cn("db-msg", className)}
      {...props}
    />
  )
}

/** The face beside the message. It sits in the message's grid, so it must be a direct child. */
function MessageAvatar({ className, ...props }: AvatarProps) {
  // The header already names the person, so the ring is decoration for assistive tech.
  return <Avatar data-slot="message-avatar" aria-hidden="true" className={className} {...props} />
}

type MessageHeaderProps = Omit<React.ComponentProps<"header">, "children"> & {
  name: React.ReactNode
  time: React.ReactNode
  /** The machine-readable time, such as 2026-09-30T09:40. */
  dateTime?: string
}

/** The name and the time. Yours flips them, time first, so the name stays beside your avatar. */
function MessageHeader({ name, time, dateTime, className, ...props }: MessageHeaderProps) {
  return (
    <header data-slot="message-header" className={cn("db-msg-head", className)} {...props}>
      <b>{name}</b>
      <time dateTime={dateTime}>{time}</time>
    </header>
  )
}

function MessageBody({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="message-body" className={cn("db-msg-body", className)} {...props} />
}

type MessageBubbleProps = React.ComponentProps<"p"> & {
  /** Which side the tail leans to. Set "end" for what you wrote. */
  align?: "start" | "end"
  /** ink: reversed type in a block, the tail under it. mark: a highlighter behind the words. */
  variant?: "default" | "ink" | "mark"
}

/** No balloon. Of the speech bubble only its tail is left, a leaning hairline. */
function MessageBubble({ align = "start", variant = "default", className, children, ...props }: MessageBubbleProps) {
  const shared = {
    "data-slot": "message-bubble",
    "data-align": align === "end" ? "end" : undefined,
    "data-variant": variant === "default" ? undefined : variant,
  }
  // The highlighter needs an inline paragraph inside the block, so the marker wraps.
  if (variant === "mark") {
    return (
      <div {...shared} className={cn("db-bubble", className)} {...(props as React.ComponentProps<"div">)}>
        <p>{children}</p>
      </div>
    )
  }
  return (
    <p {...shared} className={cn("db-bubble", className)} {...props}>
      {children}
    </p>
  )
}

type MessageTypingProps = Omit<React.ComponentProps<"p">, "children"> & {
  /** True only while the other side is writing. Keep it mounted and drive this, so the words are heard when it starts. */
  writing: boolean
  /** What a screen reader hears while it shows, such as "Ada is writing". */
  label?: string
  /** Which side the tail leans to, as on a bubble. */
  align?: "start" | "end"
}

/**
 * The other side is writing: the tail and three periods where their words will be, in pencil, breathing
 * as a busy button's do. Not writing, it stays mounted as an empty, silent status that takes no room.
 */
function MessageTyping({ writing, label = "Writing", align = "start", className, ...props }: MessageTypingProps) {
  return (
    <p
      data-slot="message-typing"
      data-writing={writing || undefined}
      data-align={align === "end" ? "end" : undefined}
      role="status"
      className={cn("db-bubble db-typing", !writing && "db-sr", className)}
      {...props}
    >
      {writing ? (
        <>
          <Spinner />
          <span className="db-sr">{label}</span>
        </>
      ) : null}
    </p>
  )
}

function MessageFooter({ className, ...props }: React.ComponentProps<"footer">) {
  return <footer data-slot="message-footer" className={cn("db-msg-foot", className)} {...props} />
}

type MessageStatusProps = Omit<React.ComponentProps<"span">, "children"> & {
  /** Sent is a ring; read, it fills to a dot. */
  read?: boolean
  /** The word. Defaults to "Sent" or "Read". */
  children?: React.ReactNode
}

/** The word and its dot, side by side in the footer. */
function MessageStatus({ read, children, className, ...props }: MessageStatusProps) {
  return (
    <>
      <span>{children ?? (read ? "Read" : "Sent")}</span>
      <span data-slot="message-status" data-read={read || undefined} aria-hidden="true" className={cn("db-msg-status", className)} {...props} />
    </>
  )
}

function MessageReactions({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="message-reactions" role="group" aria-label="Reactions" className={cn("db-reactions", className)} {...props} />
}

type MessageReactionProps = Omit<React.ComponentProps<"button">, "onClick"> & {
  defaultPressed?: boolean
  /** How many people reacted, including you if pressed. */
  defaultCount?: number
  /** Called after the count has rolled. */
  onPressedChange?: (pressed: boolean, count: number) => void
}

/** A reaction: a tag you can press. Yours turns italic and the count rolls. */
// ponytail: uncontrolled; lift pressed and count to props when a thread needs to own them.
function MessageReaction({ defaultPressed = false, defaultCount = 0, onPressedChange, className, children, ...props }: MessageReactionProps) {
  const [pressed, setPressed] = React.useState(defaultPressed)
  const [count, setCount] = React.useState(defaultCount)
  const counter = React.useRef<HTMLSpanElement>(null)

  const toggle = () => {
    const on = !pressed
    const n = count + (on ? 1 : -1)
    setPressed(on)
    if (counter.current) roll(counter.current, () => setCount(n), "0.5em", on ? 1 : -1)
    else setCount(n)
    onPressedChange?.(on, n)
  }

  return (
    <button type="button" data-slot="message-reaction" aria-pressed={pressed} className={cn("db-tag", className)} onClick={toggle} {...props}>
      <span>{children}</span>
      <span ref={counter} className="db-reaction-count">{count}</span>
    </button>
  )
}

export {
  Message,
  MessageAvatar,
  MessageHeader,
  MessageBody,
  MessageBubble,
  MessageTyping,
  MessageFooter,
  MessageStatus,
  MessageReactions,
  MessageReaction,
  type MessageProps,
  type MessageTypingProps,
}

@layer components {
  /* ── db-msg ── a message: what they wrote is roman, what you wrote is italic */
  .db-msg {
    display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "face head" "face body" ". foot";
    column-gap: var(--db-space-5); row-gap: var(--db-space-1); max-width: 34rem;
  }
  .db-msg > .db-avatar { --s: 2.25rem; grid-area: face; align-self: start; }
  .db-msg-head { display: flex; align-items: baseline; gap: var(--db-space-3); font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); }
  .db-msg-head > b { font-weight: 500; color: var(--db-ink); }
  .db-msg-body { color: var(--db-ink); }
  .db-msg-foot { display: flex; flex-wrap: wrap; align-items: center; gap: var(--db-space-2); margin-top: var(--db-space-2); font-size: var(--db-pp); color: var(--db-pencil); }
  /* Placed by name only inside a message: elsewhere (the docs' states) they are plain blocks. */
  .db-msg > .db-msg-head { grid-area: head; }
  .db-msg > .db-msg-body { grid-area: body; }
  .db-msg > .db-msg-foot { grid-area: foot; }
  .db-msg[data-from="you"] { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "head face" "body face" "foot ."; margin-inline-start: auto; text-align: end; }
  .db-msg[data-from="you"] :is(.db-msg-head, .db-msg-foot) { justify-content: flex-end; }
  .db-msg[data-from="you"] .db-msg-body { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1.4; }
  .db-msg[data-arriving] .db-msg-body { animation: db-message-write var(--db-andante) var(--db-exhale) backwards; }
  @keyframes db-message-write { from { clip-path: inset(0 100% 0 0); } }
  /* The words write in from the inline start, so from the right on a right-to-left page. */
  :is([dir="rtl"], [dir="rtl"] *) .db-msg[data-arriving] .db-msg-body { animation-name: db-message-write-rtl; }
  @keyframes db-message-write-rtl { from { clip-path: inset(0 0 0 100%); } }
  /* Yours: the time comes first, then the name, next to the avatar. */
  .db-msg[data-from="you"] .db-msg-head > time { order: -1; }
  /* Sent is a ring; read, it fills to a dot, like the switch's full stop. */
  .db-msg-status { display: inline-block; width: 6px; height: 6px; border-radius: 50%; box-shadow: inset 0 0 0 var(--db-hairline) currentColor; transition: box-shadow var(--db-andante) var(--db-exhale); }
  .db-msg-status[data-read] { box-shadow: inset 0 0 0 4px currentColor; }

  /* ── db-bubble ── the speech balloon is gone; only its tail is left */
  .db-bubble { position: relative; padding-inline-start: 1.1em; }
  .db-bubble::before { content: ""; position: absolute; inset-inline-start: 0.65em; top: 0.4em; width: var(--db-hairline); height: 0.8em; background: var(--db-ink); rotate: 38deg; transform-origin: 50% 0; }
  .db-bubble[data-align="end"] { padding-inline: 0 1.1em; }
  .db-bubble[data-align="end"]::before { inset-inline: auto 0.65em; rotate: -38deg; }
  /* In a message the tail hangs in the gutter beside the avatar, so the words share the name's edge. */
  .db-msg-body > .db-bubble:not([data-variant="ink"]) { margin-inline-start: -1.1em; }
  .db-msg-body > .db-bubble[data-align="end"]:not([data-variant="ink"]) { margin-inline: 0 -1.1em; }
  :is([dir="rtl"], [dir="rtl"] *) .db-bubble::before { rotate: -38deg; }
  :is([dir="rtl"], [dir="rtl"] *) .db-bubble[data-align="end"]::before { rotate: 38deg; }
  .db-bubble[data-variant="ink"] { padding: 0.55em 0.95em 0.6em; background: var(--db-ink); color: var(--db-paper); }
  .db-bubble[data-variant="ink"]::before { inset-inline-start: 0.9em; top: 100%; height: 0.7em; }
  .db-bubble[data-variant="mark"] > p { display: inline; padding: 0 0.12em; background: var(--db-mark); color: var(--db-on-mark); -webkit-box-decoration-break: clone; box-decoration-break: clone; }
  /* Selected inside the highlighter, the words reverse, as they do in a mark: yellow on yellow would lose them. */
  .db-bubble[data-variant="mark"] > p ::selection, .db-bubble[data-variant="mark"] > p::selection { background: var(--db-ink); color: var(--db-paper); }
  /* typing: the other side is writing. Only the tail and three periods where the words will be, sketched in pencil
     until the message inks them in. Shown only while they write (data-writing); otherwise a silent, empty status (.db-sr). */
  .db-typing[data-writing] { color: var(--db-pencil); animation: db-arrive var(--db-moderato) var(--db-exhale) backwards; }
  .db-typing::before { background: currentColor; }
  /* A message that holds a silent typing status folds away with it (as .db-sr does), so it can stay mounted, face and all. */
  .db-msg:has(> .db-msg-body > .db-typing:not([data-writing])) { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .db-reactions { display: flex; flex-wrap: wrap; gap: var(--db-space-2); }
  .db-reactions > .db-tag[aria-pressed="true"] { color: var(--db-ink); box-shadow: inset 0 0 0 var(--db-hairline) var(--db-ink); }
  .db-reactions > .db-tag[aria-pressed="true"] > :first-child { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1; }
  .db-reaction-count { display: inline-block; color: var(--db-pencil); font-variant-numeric: tabular-nums; }

  /* ── script ── a play text: the name in caps in the margin, the words in the column, one column for everyone.
     Who is speaking shows only in the type: theirs roman, yours italic. The time is a stage direction, in parentheses. */
  .db-msg[data-variant="script"], .db-msg[data-variant="script"][data-from="you"] {
    grid-template-columns: 8.5rem minmax(0, 1fr); grid-template-areas: "head body" ". foot"; align-items: baseline;
    max-width: 40rem; margin-inline-start: 0; text-align: start;
  }
  .db-msg:is([data-variant="script"], [data-variant="quote"]) > .db-avatar { display: none; }
  .db-msg[data-variant="script"] > .db-msg-head { flex-direction: column; align-items: flex-end; justify-content: flex-start; gap: 0; text-align: end; }
  .db-msg[data-variant="script"] .db-msg-head > b { font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; }
  .db-msg[data-variant="script"] .db-msg-head > b::after { content: "." / ""; }
  .db-msg[data-variant="script"] .db-msg-head > time { order: 0; font-variant-numeric: tabular-nums; }
  .db-msg[data-variant="script"] .db-msg-head > time::before { content: "(" / ""; }
  .db-msg[data-variant="script"] .db-msg-head > time::after { content: ")" / ""; }
  .db-msg[data-variant="script"] > .db-msg-foot { justify-content: flex-start; }
  /* Script and quote have no balloon at all: the tail goes, and the words keep the column's edge. */
  .db-msg:is([data-variant="script"], [data-variant="quote"]) .db-bubble::before { display: none; }
  .db-msg:is([data-variant="script"], [data-variant="quote"]) .db-msg-body > .db-bubble { margin-inline: 0; }
  .db-msg:is([data-variant="script"], [data-variant="quote"]) .db-msg-body > .db-bubble:not([data-variant="ink"]) { padding-inline: 0; }
  @media (max-width: 30rem) {
    .db-msg[data-variant="script"], .db-msg[data-variant="script"][data-from="you"] { grid-template-columns: minmax(0, 1fr); grid-template-areas: "head" "body" "foot"; }
    .db-msg[data-variant="script"] > .db-msg-head { flex-direction: row; align-items: baseline; gap: var(--db-space-3); }
  }

  /* ── quote ── the typographer's speech balloon: a large italic quotation mark where the face was.
     Theirs opens at the top of the start; yours closes at the foot of the end, so each exchange is framed from both sides. */
  .db-msg[data-variant="quote"]::before {
    content: "\201C" / ""; grid-area: face; align-self: start; margin-block-start: -0.08em;
    font: italic 400 var(--db-ff) / 0.8 var(--db-expression); color: var(--db-pencil);
  }
  .db-msg[data-variant="quote"][data-from="you"]::before { content: "\201D" / ""; align-self: end; margin-block: 0 -0.42em; }
  :is([dir="rtl"], [dir="rtl"] *) .db-msg[data-variant="quote"]::before { scale: -1 1; }
  .db-msg[data-variant="quote"][data-arriving]::before { animation: db-message-quote var(--db-moderato) var(--db-spiccato) backwards; }
  @keyframes db-message-quote { from { opacity: 0; translate: 0 -0.12em; } }
  @media (forced-colors: active) {
    .db-msg[data-variant="quote"]::before { color: GrayText; }
  }
}
